import json,sys,os
s=sys.argv[1]
lines=open(os.path.join(s,"messages.jsonl")).readlines()
for i,line in enumerate(lines,1):
    if i<20: continue
    d=json.loads(line); m=d["message"]; role=m.get("role")
    c=m.get("content")
    if role=="assistant":
        parts=[]
        for x in (c or []):
            if not isinstance(x,dict): continue
            if x.get("type")=="text": parts.append("TEXT: "+x["text"])
            elif x.get("type")=="toolCall":
                args=json.dumps(x.get("arguments",{}))
                parts.append(f"TOOL {x.get('name')}: {args[:600]}")
        if parts: print(f"\n--- [{i}] assistant ---\n"+"\n".join(p[:1400] for p in parts))
    elif role=="toolResult":
        txt=" ".join(x.get("text","") for x in (c or []) if isinstance(x,dict))
        print(f"  [{i}] RESULT({m.get('toolName')}): {txt[:500]}")
EOF

